// A project generated by CLI 1.x, upgraded (spec/cli/outputs.md, section 7): its standard
// names version 1 of a pack that is now version 2, and its old build/<env>/ folders are
// reported as no longer generated, never changed, until the user deletes them.
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { edit, workspace } from "./workspace.js";

/** A folder as CLI 1.x left it: its files, and a manifest that lists each with its hash. */
function generatedBefore(root: string, files: Record<string, string>): void {
  const hashes: Record<string, string> = {};
  for (const [path, text] of Object.entries(files)) {
    mkdirSync(join(root, path, ".."), { recursive: true });
    writeFileSync(join(root, path), text);
    hashes[path] = `sha256:${createHash("sha256").update(text).digest("hex")}`;
  }
  writeFileSync(
    join(root, ".generated.json"),
    `${JSON.stringify({ version: 1, files: hashes })}\n`,
  );
}

const retired = (folder: string) =>
  `${folder}: no longer generated. Delete the folder, or delete its .generated.json to keep it as your own.`;

describe("a project upgraded from CLI 1.x", () => {
  it("shows PACK_VERSION once for every environment, with the fix, and writes nothing", () => {
    const { folder, ingestron } = workspace("private-files", (root) =>
      edit(root, "standard.yaml", "[databricks@2, adf@2]", "[databricks@1, adf@1]"),
    );
    const { code, output } = ingestron("plan");
    expect(code).toBe(1);
    expect(output.split("\n")[0]).toBe("dev, prod: the definitions have problems");
    expect(output.match(/error {2}PACK_VERSION/g)).toHaveLength(2);
    expect(output).toContain('Fix: Change to "databricks@2".');
    expect(output).toContain('Fix: Change to "adf@2".');
    expect(output.match(/the definitions have problems/g)).toHaveLength(1);
    expect(existsSync(join(folder, "build"))).toBe(false);
  });

  it("shows PACK_VERSION, with the fix to duckdb@2, for a DuckDB project's duckdb@1", () => {
    const { ingestron } = workspace("duckdb", (root) =>
      edit(root, "standard.yaml", "[duckdb@2]", "[duckdb@1]"),
    );
    const { code, output } = ingestron("plan");
    expect(code).toBe(1);
    expect(output).toContain(
      'error  PACK_VERSION\n  This standard is for "duckdb@1", but the pack is duckdb@2.\n',
    );
    expect(output).toContain('Fix: Change to "duckdb@2".');
  });

  it("reports each pack's and the passports' old folders, keeps an edited file, and checks once they are deleted", () => {
    const { folder, ingestron } = workspace("private-files", (root) => {
      for (const environment of ["dev", "prod"]) {
        const old = join(root, "build", environment);
        generatedBefore(join(old, "databricks"), { "databricks.yml": "bundle: {}\n" });
        generatedBefore(join(old, "adf"), { "pipeline/pl_stores_share.json": "{}\n" });
        generatedBefore(join(old, "products"), { "README.md": "# Data products\n" });
      }
      // Edited by hand after 1.x generated it.
      writeFileSync(join(root, "build/dev/databricks/databricks.yml"), "bundle: { name: mine }\n");
    });
    const apply = ingestron("apply");
    expect(apply.code, apply.output).toBe(0);
    for (const environment of ["dev", "prod"])
      for (const pack of ["adf", "databricks", "products"])
        expect(apply.output).toContain(retired(`build/${environment}/${pack}`));
    expect(apply.output).not.toContain(retired("build/dev"));
    expect(readFileSync(join(folder, "build/dev/databricks/databricks.yml"), "utf8")).toBe(
      "bundle: { name: mine }\n",
    );
    const check = ingestron("check");
    expect(check.code).toBe(1);
    expect(check.output).toContain("databricks: up to date\nadf: up to date\n");
    for (const environment of ["dev", "prod"])
      rmSync(join(folder, "build", environment), { recursive: true });
    const clean = ingestron("check");
    expect(clean.code, clean.output).toBe(0);
    expect(clean.output).not.toContain("no longer generated");
  });
});
